import{_ as t,o,c as s,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"TTS Providers","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/providers/tts/index.md","filePath":"integrations/providers/tts/index.md","lastUpdated":1781609185000}'),a={name:"integrations/providers/tts/index.md"};function i(d,e,n,l,c,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="tts-providers" tabindex="-1">TTS Providers <a class="header-anchor" href="#tts-providers" aria-label="Permalink to &quot;TTS Providers&quot;">​</a></h1><p>Memoh supports <strong>Text-to-Speech (TTS)</strong> so bots can synthesize spoken audio from text. The TTS system is organized into three layers:</p><ul><li><strong>TTS Provider</strong>: A service type (e.g. Edge TTS). You create named provider instances from the TTS Providers page.</li><li><strong>TTS Model</strong>: A specific voice/model under a provider (e.g. <code>edge-read-aloud</code>). Models have configurable voice, format, speed, and pitch settings.</li><li><strong>Bot Assignment</strong>: In Bot Settings, select a TTS Model. The bot can then synthesize speech in conversations.</li></ul><hr><h2 id="basic-flow" tabindex="-1">Basic Flow <a class="header-anchor" href="#basic-flow" aria-label="Permalink to &quot;Basic Flow&quot;">​</a></h2><ol><li>Navigate to the <strong>TTS Providers</strong> page from the sidebar.</li><li>Click <strong>Add</strong> and select a provider type (e.g. <code>edge</code>).</li><li>Click <strong>Create</strong> — the provider&#39;s default model is auto-imported.</li><li>Click the model to configure voice, format, speed, and pitch.</li><li>Test synthesis with the built-in test button.</li><li>Open a bot&#39;s <strong>General</strong> tab and select the TTS Model.</li><li>Save — the bot can now synthesize speech.</li></ol><hr><h2 id="available-speech-providers" tabindex="-1">Available Speech Providers <a class="header-anchor" href="#available-speech-providers" aria-label="Permalink to &quot;Available Speech Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Description</th></tr></thead><tbody><tr><td><a href="/integrations/providers/tts/edge.html">Edge TTS</a></td><td>Free, uses Microsoft Edge&#39;s public read-aloud API. 256+ voices across 50+ languages. No API key required.</td></tr><tr><td>OpenAI-compatible speech</td><td>Uses OpenAI-compatible speech APIs when configured with a matching provider template and credentials.</td></tr><tr><td>OpenRouter Speech</td><td>Uses OpenRouter speech-capable routes when available to the configured account.</td></tr><tr><td>ElevenLabs Speech</td><td>Uses ElevenLabs text-to-speech models and voices.</td></tr><tr><td>Deepgram Speech</td><td>Uses Deepgram text-to-speech models.</td></tr><tr><td>MiniMax Speech</td><td>Uses MiniMax text-to-speech models.</td></tr><tr><td>Volcengine Speech</td><td>Uses Volcengine speech synthesis models.</td></tr><tr><td>Alibaba Cloud Speech</td><td>Uses Alibaba Cloud speech synthesis models.</td></tr><tr><td>Microsoft Speech</td><td>Uses Microsoft speech synthesis models.</td></tr></tbody></table><p>Exact model, voice, format, and language availability depends on the provider template and upstream account you configure.</p><p>Transcription is managed separately from TTS. Memoh also supports transcription provider categories for OpenAI-compatible, OpenRouter, ElevenLabs, Deepgram, and Google speech-to-text workflows.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>To set up the no-key Edge option, continue with <a href="/integrations/providers/tts/edge.html">Edge TTS</a>.</li><li>To understand how audio provider client types relate to models, see <a href="/integrations/providers/llm.html">Providers And Models</a>.</li></ul>',14)])])}const m=t(a,[["render",i]]);export{g as __pageData,m as default};
